import{_ as o,o as d,c as t,a2 as s}from"./chunks/framework.p9eYlHBT.js";const u=JSON.parse('{"title":"群聊（G1 后端：契约冻结 v1.0 实现说明）","description":"","frontmatter":{},"headers":[],"relativePath":"GROUPS.md","filePath":"GROUPS.md","lastUpdated":1794410944000}'),c={name:"GROUPS.md"};function a(i,e,r,n,l,p){return d(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="群聊-g1-后端-契约冻结-v1-0-实现说明" tabindex="-1">群聊（G1 后端：契约冻结 v1.0 实现说明） <a class="header-anchor" href="#群聊-g1-后端-契约冻结-v1-0-实现说明" aria-label="Permalink to &quot;群聊（G1 后端：契约冻结 v1.0 实现说明）&quot;">​</a></h1><blockquote><p>契约来源：issue 里 KG 冻结的 <strong>G1 API 契约 v1.0</strong>（<code>web-ui/src/api/types.ts</code> 群聊段与之同形）。 实现：<code>packages/agent/src/agent-group-store.ts</code>、<code>packages/server/src/agent-group-service.ts</code>、 <code>packages/server/src/routes/groups.ts</code>、<code>packages/tools/src/builtin/group-tools.ts</code>。</p></blockquote><h2 id="_1-模型-对话聚合-vs-生命周期聚合" tabindex="-1">1. 模型：对话聚合 vs 生命周期聚合 <a class="header-anchor" href="#_1-模型-对话聚合-vs-生命周期聚合" aria-label="Permalink to &quot;1. 模型：对话聚合 vs 生命周期聚合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>角色</th><th>关键字段</th></tr></thead><tbody><tr><td><code>agent_groups</code></td><td>群（对话聚合根）</td><td><code>id(grp_…)</code> / <code>name</code> / <code>description</code> / \`status(open</td></tr><tr><td><code>group_messages</code></td><td>群聊日志（append-only）</td><td><code>id(msg_…)</code> / <code>seq</code>（群内单调，1 起） / <code>from_kind</code> / <code>from_name</code> / <code>content</code> / <code>kind</code> / <code>agent_task_id</code></td></tr></tbody></table><ul><li>任务不进群表：群内派发复用 <code>agent_tasks</code>（G2 加 <code>groupId</code> 语义），群消息只用 <code>agentTaskId</code> 反指任务 —— 7 态状态机不受影响。</li><li><code>members_json</code> 存成员（runtime + 协调者），<strong>对外 <code>members</code> = runtime 名列表</strong>（人隐含在场， 不占位；协调者 <code>fengagent</code> 会出现在列表里）。</li><li><code>kind</code>：<code>chat</code>（G1 默认）/ <code>task_card</code>（G2）/ <code>decision</code>（G3）/ <code>system</code>（建群等系统提示）。</li></ul><h2 id="_2-http-api-与契约逐条对齐" tabindex="-1">2. HTTP API（与契约逐条对齐） <a class="header-anchor" href="#_2-http-api-与契约逐条对齐" aria-label="Permalink to &quot;2. HTTP API（与契约逐条对齐）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>请求</th><th>响应</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/groups</code></td><td><code>status</code> / <code>limit</code>（可选）</td><td><code>{groups: GroupInfo[], runtimes: RuntimeInfo[]}</code></td></tr><tr><td>POST</td><td><code>/api/groups</code></td><td><code>{name, description?, members: string[], maxRounds?, speechMode?}</code></td><td>201 <code>GroupInfo</code>；成员未注册/未启用 → <strong>400</strong></td></tr><tr><td>GET</td><td><code>/api/groups/:id</code></td><td>—</td><td><code>{group, messages}</code>（<strong>全量</strong>消息，G1 不分页）</td></tr><tr><td>POST</td><td><code>/api/groups/:id/messages</code></td><td><code>{content, kind?: &quot;chat&quot;}</code></td><td>201 <code>GroupMessage</code>（<code>fromKind=human</code>、<code>fromName=human</code>）；已 <code>concluded</code> → <strong>409</strong></td></tr><tr><td>POST</td><td><code>/api/groups/:id/agent-messages</code></td><td><code>{content, fromName, kind?}</code></td><td>201 <code>GroupMessage</code>（协调者 → <code>coordinator</code>，成员 runtime → <code>runtime</code>）；非成员 → <strong>403</strong>；已关群 → 409</td></tr><tr><td>POST</td><td><code>/api/groups/:id/conclude</code></td><td>—</td><td><code>GroupInfo</code>（<code>status=concluded</code>，<strong>幂等</strong>：重复调用返回原样）</td></tr><tr><td>PATCH</td><td><code>/api/groups/:id</code></td><td><code>{name?, description?, members?, maxRounds?, speechMode?}</code></td><td><code>GroupInfo</code>（契约外的便利接口，改名/改成员/切模式用）</td></tr><tr><td>GET</td><td><code>/api/groups/:id/messages</code></td><td><code>after</code> / <code>limit</code>（可选）</td><td><code>{messages, nextSeq}</code>（增量读取；SSE 重连同款语义）</td></tr><tr><td>GET</td><td><code>/api/groups/:id/stream</code></td><td><code>after</code>（可选，默认 0）</td><td>群 SSE（见 §3）</td></tr></tbody></table><p><strong>错误体</strong>统一 <code>{ error: { message, code } }</code>，<code>code ∈ bad_request | forbidden | not_found | conflict</code>， HTTP 状态 400 / 403 / 404 / 409。</p><p><strong>DTO</strong>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GroupInfo   { id, name, description, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">members</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string[], </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;open&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;concluded&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">              maxRounds, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">speechMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;coordinated&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;free&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, createdAt, updatedAt, lastMessageAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GroupMessage{ id, groupId, seq, fromKind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;human&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;runtime&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;coordinator&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">              fromName, content, kind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;chat&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;task_card&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;decision&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">              agentTaskId?, createdAt }</span></span></code></pre></div><p>建群时会自动落一条 <code>system</code> 消息「群已创建」（<code>fromName=&quot;system&quot;</code>）。</p><h2 id="_3-群-sse" tabindex="-1">3. 群 SSE <a class="header-anchor" href="#_3-群-sse" aria-label="Permalink to &quot;3. 群 SSE&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/groups/:id/stream?after=&lt;seq&gt;       # 也接受 Last-Event-ID</span></span></code></pre></div><ul><li>首帧 <strong><code>snapshot</code></strong>：<code>{type:&quot;snapshot&quot;, group, messages:[after 之后的消息], lastSeq}</code>（一次给全）；</li><li>实时：<code>{type:&quot;message&quot;, message}</code>（SSE <code>id: &lt;seq&gt;</code>，可 Last-Event-ID 去重）、 <code>{type:&quot;group&quot;, group}</code>（conclude 等属性变更）；</li><li>心跳：<code>{type:&quot;heartbeat&quot;}</code> 数据帧，15s 一条；</li><li>群删除时结束流（G1 无删除接口，预留）。</li></ul><h2 id="_4-谁能发言-v1-协调者中转" tabindex="-1">4. 谁能发言（v1 协调者中转） <a class="header-anchor" href="#_4-谁能发言-v1-协调者中转" aria-label="Permalink to &quot;4. 谁能发言（v1 协调者中转）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>写入路径</th><th><code>from_kind</code> / <code>from_name</code></th></tr></thead><tbody><tr><td>人</td><td><code>POST /:id/messages</code></td><td><code>human</code> / <code>human</code></td></tr><tr><td>协调者（群内 fengagent）</td><td>群工具 <code>group_send</code> → <code>POST /:id/agent-messages</code></td><td><code>coordinator</code> / <code>fengagent</code></td></tr><tr><td>成员 runtime（G2 起）</td><td><code>POST /:id/agent-messages</code>（服务端装配调用）</td><td><code>runtime</code> / 成员 runtime 名</td></tr><tr><td>外部 runtime 的产出</td><td><strong>服务端代写</strong>：<code>postRuntimeMessage()</code>（G2 结果回群主路径，不开放 REST）</td><td><code>runtime</code> / runtime 名</td></tr><tr><td>系统</td><td><code>postSystemMessage()</code></td><td><code>system</code> / <code>system</code></td></tr></tbody></table><p>外部 runtime <strong>没有</strong>群工具（要注入 MCP，G4/v2）；它们的产出统一由服务端写进群并带 <code>agentTaskId</code> 深链 —— 不依赖成员自觉，也不会「某个 runtime 忘了发消息」。</p><h2 id="_5-群工具-只注入本仓库-fengagent-侧-契约三个" tabindex="-1">5. 群工具（只注入本仓库 fengagent 侧，契约三个） <a class="header-anchor" href="#_5-群工具-只注入本仓库-fengagent-侧-契约三个" aria-label="Permalink to &quot;5. 群工具（只注入本仓库 fengagent 侧，契约三个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>入参</th><th>作用</th></tr></thead><tbody><tr><td><code>group_create</code></td><td><code>{name, description?, members?: string[]}</code></td><td>建群（协调者 = <code>FENG_GROUP_SELF_NAME</code>，默认 <code>fengagent</code>）</td></tr><tr><td><code>group_send</code></td><td><code>{groupId, content}</code></td><td>以协调者身份发言 → <code>coordinator</code></td></tr><tr><td><code>group_history</code></td><td><code>{groupId, limit?}</code></td><td>读最近 N 条（旧→新，<code>#seq [from] content</code>）</td></tr></tbody></table><p>工具由 server 装配注入（<code>createRuntimeAgent</code> → <code>createGroupTools(handler)</code>），tools 包不 反向依赖 server。<code>group_conclude</code> / <code>group_dispatch</code> 属于 G3 / G2，本轮不放。</p><h2 id="_6-g2-已实现-群内派发-结果回群" tabindex="-1">6. G2（已实现）：群内派发 + 结果回群 <a class="header-anchor" href="#_6-g2-已实现-群内派发-结果回群" aria-label="Permalink to &quot;6. G2（已实现）：群内派发 + 结果回群&quot;">​</a></h2><ul><li><strong>任务带群</strong>：<code>POST /api/agent-tasks</code> 与 <code>dispatch_task</code> 都接受 <code>groupId</code>；任务记录新增 <code>group_id</code>（老库自动 <code>ALTER TABLE</code> 补列 + 索引），任务 DTO 回显 <code>groupId</code>； <code>GET /api/agent-tasks?groupId=</code> 只列该群任务。</li><li><strong>结果回群（服务端代写）</strong>：任务终态时 <code>AgentTaskService</code> 通过下沉口 <code>groupSink</code> 调 <code>postRuntimeMessage(groupId, {runtime, content, agentTaskId, kind:&quot;task_card&quot;})</code>： <ul><li><code>replied</code> → 「任务 xxx（runtime）已完成：&lt;结果&gt;」（超 2000 字截断）；</li><li><code>failed</code> → 「任务 xxx（runtime）失败：&lt;错误&gt;」（超 1500 字截断）；</li><li><code>cancelled</code> → 「任务 xxx（runtime）已取消」。 消息 <code>fromKind=&quot;runtime&quot;</code>、<code>fromName=&lt;runtime&gt;</code>、<code>kind=&quot;task_card&quot;</code>、带 <code>agentTaskId</code>。 后端只保证 <code>agentTaskId</code> 这个锚点，<strong>跳转路由由前端决定</strong>（<code>/agents?task=&lt;id&gt;</code> 或 <code>?view=agents&amp;task=&lt;id&gt;</code> 都行）。群侧写失败只 warn，不影响任务已收尾的事实。</li></ul></li><li><strong>提交即验群</strong>：<code>submit()</code> 带 <code>groupId</code> 时先用 <code>groupSink.hasGroup()</code> 校验，未知群直接 400（否则任务跑完才发现结果无处可回）。</li><li><strong>不带 <code>groupId</code> 的任务不回群</strong>（回归用例覆盖）。</li></ul><h2 id="_7-g3-已实现-编排收敛-人在环" tabindex="-1">7. G3（已实现）：编排收敛 + 人在环 <a class="header-anchor" href="#_7-g3-已实现-编排收敛-人在环" aria-label="Permalink to &quot;7. G3（已实现）：编排收敛 + 人在环&quot;">​</a></h2><p><code>GroupOrchestrator</code>（<code>packages/groups/src/group-orchestrator.ts</code>）三条独立策略，共用一个 <strong>幂等 <code>conclude()</code></strong>：</p><table tabindex="0"><thead><tr><th>策略</th><th>触发</th><th>行为</th></tr></thead><tbody><tr><td>轮次上限 <code>maxRounds</code></td><td>同群内「自上次人类发言以来」协调者发言数达到上限</td><td>自动收口（system 说明原因）；人类发言清零计数</td></tr><tr><td>静默超时 <code>idleTimeoutMs</code></td><td>群 open 且最后一条消息距今 ≥ 阈值（生产 5s 扫一次；测试手动 <code>sweepIdle</code>）</td><td>自动收口</td></tr><tr><td>人类拍板</td><td>human 发 <code>kind:&quot;decision&quot;</code> 的消息</td><td>该消息落库后立即收口</td></tr></tbody></table><ul><li><strong>收口顺序</strong>：写 <code>【收口】原因</code> 的 system 消息 → 取消该群未终态任务（<code>cancelledTasks</code>， 有则再补一条「已取消 N 个在跑任务」）→ 群状态置 <code>concluded</code>。消息只能在 open 群写入， 所以顺序不能反。重复收口返回 <code>concluded:false</code>（幂等）。</li><li><strong>人类中途关停</strong>：<code>POST /api/groups/:id/stop</code> → <code>{group, cancelledTasks}</code>（关群 + 取消任务， 对应验收口径「关群后无残留任务」）。</li><li><strong><code>POST /:id/conclude</code></strong> 在有编排器时也走同一条路径（留收口说明）。</li><li><strong><code>group_conclude</code> 工具</strong>（第 4 个群工具）：协调者把结论以 <code>decision</code> 消息落库 → 关群 → 报告取消任务数；返回 <code>status</code> + <code>cancelledTasks</code>。</li><li><strong><code>decision</code> 消息</strong>：<code>kind=&quot;decision&quot;</code>，人类拍板与协调者结论都用它，前端可单独渲染。</li><li><strong>HTTP 入口（G3 补）</strong>： <ul><li>人类拍板：<code>POST /api/groups/:id/messages {content, kind:&quot;decision&quot;}</code> → 201 并立即收口 （<code>kind</code> 白名单 <code>chat | decision</code>，其它值 400；<code>task_card</code> 只由服务端代写）。</li><li>静默超时可配：<code>POST /api/groups</code> 与 <code>PATCH /api/groups/:id</code> 接受 <code>idleTimeoutMs</code> （默认 600000），<code>GroupInfo</code> 回显该字段供前端展示。</li></ul></li></ul><h2 id="_8-v2-3-已实现-自治发言-——-speechmode-发言预算-仲裁-轮数升级" tabindex="-1">8. V2-3（已实现）：自治发言 —— <code>speechMode</code> / 发言预算 / @ 仲裁 / 轮数升级 <a class="header-anchor" href="#_8-v2-3-已实现-自治发言-——-speechmode-发言预算-仲裁-轮数升级" aria-label="Permalink to &quot;8. V2-3（已实现）：自治发言 —— \`speechMode\` / 发言预算 / @ 仲裁 / 轮数升级&quot;">​</a></h2><p>外部 agent 经 MCP 直连发言后，「谁说、何时说、何时停」从协调者调度变成域层策略。 落点在 <code>@fengagent/groups</code>（<code>AgentGroupService</code> + <code>GroupOrchestrator</code>），<strong>不新增调度进程</strong>：</p><table tabindex="0"><thead><tr><th><code>speechMode</code></th><th>语义</th></tr></thead><tbody><tr><td><code>coordinated</code>（缺省，v1 兼容）</td><td>只有协调者调度回合；成员直连发言仍可用，但<strong>不计轮、不占预算、不参与仲裁</strong>（中途求助不改轮次模型）</td></tr><tr><td><code>free</code>（自治）</td><td>成员之间直接发言/求助，收敛靠下面四闸</td></tr></tbody></table><p>free 模式四闸：</p><ol><li><strong>轮数升级</strong>：<code>maxRounds</code> 是<strong>总轮数</strong>，一轮 = 一名成员的一组连续发言（同一人连发不增轮， 换人才 +1）；人类发言把轮数清零。到上限自动收口（system 说明写明「free 模式共 N 轮」）。</li><li><strong>发言预算</strong>：每成员每窗口最多 N 条（<code>GroupOrchestratorOptions.speechBudget</code>，默认 5 条 / 60s， 按成员分别计窗；协调者不计）。超预算的发言在<strong>落库前</strong>被拒： <code>GroupError{code:&quot;conflict&quot;}</code> → HTTP <strong>409</strong>，消息不落库、不广播。</li><li><strong>发言权仲裁</strong>：消息正文里 <code>@某人</code>（MCP 的 <code>group_reply</code> 同样只是发一条带 <code>@</code> 的消息）→ 下一发言权归他；持权期间其他成员插话被拒（409）。人 / 协调者可随时发言（主持人改派）； 没人被 @ 时发言权开放。<code>arbitration:&quot;advisory&quot;</code> 只记录不拦截。 <code>onTurn(groupId, speaker)</code> 在发言权转移时回调，宿主可据此派发任务。</li><li><code>idleTimeoutMs</code> / 人类拍板不变（拍板即收口）。</li></ol><p>实现要点：</p><ul><li><strong>写前准入</strong>：<code>AgentGroupService.onBeforeMessage(hook)</code> 是新增的<strong>写前</strong>钩子 （<code>onMessage</code> 是写后观察，管不住刷屏）。<code>GroupOrchestrator</code> 构造时自动注册， free 模式下超额/抢权直接 409；钩子自身抛错按 fail-closed 处理。</li><li><strong>只拦「直接发言」</strong>：准入上下文带 <code>source</code>（<code>human</code> / <code>agent</code> / <code>system</code> / <code>task-result</code>）， 只有 <code>agent</code>（MCP、群工具、<code>agent-messages</code>）走预算与仲裁；服务端代写的任务结果 （<code>postRuntimeMessage</code>，<code>task_card</code> + <code>agentTaskId</code>）不占轮、不占预算、不改发言权，不会被 409 吞掉。</li><li><strong>状态可查询</strong>：<code>orchestrator.getStatus(groupId)</code> → <code>{speechMode, status, maxRounds, rounds, coordinatorTurns, lastSpeaker?, nextSpeaker?, budget:{limit, windowMs, used, remaining}, idleTimeoutMs}</code>，前端状态条（V2-4）直接用。</li><li><strong>持久化</strong>：<code>agent_groups.speech_mode</code>（老库自动 <code>ALTER TABLE</code> 补列，缺省 <code>coordinated</code>）； 便携 JSON store 同步补字段，老存档读成 <code>coordinated</code>。</li><li><strong>零回归</strong>：<code>coordinated</code> 下 <code>onMessage</code> 走 v1 原路径，准入恒放行；v1 用例全部保持通过。</li></ul><h2 id="_9-自测覆盖" tabindex="-1">9. 自测覆盖 <a class="header-anchor" href="#_9-自测覆盖" aria-label="Permalink to &quot;9. 自测覆盖&quot;">​</a></h2><ul><li><code>packages/agent/src/__tests__/agent-group-store.test.ts</code>（7）：建群/默认值/成员去重、 列表与状态过滤、seq 单调、<code>after</code> 增量、尾部最近消息、关群禁言、未知群拒写。</li><li><code>packages/server/src/__tests__/groups-api.test.ts</code>（9）：<code>grp_</code>/<code>msg_</code> 前缀与建群 system 消息、 <code>{groups, runtimes}</code>、未注册成员 400、人发言（<code>fromName=human</code>）与全量详情、<code>after</code> 增量、 <code>agent-messages</code>（协调者/成员/非成员 403）、<code>conclude</code> 幂等 + 关群 409 + 历史可读、 SSE <code>snapshot</code>（含 <code>lastSeq</code>）与 <code>message</code>、错误体 <code>{error:{message,code}}</code>、 群工具走通、外部 runtime 代写（<code>runtime</code> + 深链）。</li><li><code>packages/server/src/__tests__/group-dispatch.test.ts</code>（8，G2 + 关停）：replied/failed 都落 <code>task_card</code>（fromKind=runtime + agentTaskId + 内容/错误）、不带 groupId 不回群、 未知 groupId 提交即 400、API 带 groupId 与群维度列表过滤、<code>dispatch_task</code> 透传 groupId、 store 层 <code>group_id</code> 落库、<strong>真实任务服务下 stop 取消在跑任务</strong>。</li><li><code>packages/server/src/__tests__/group-orchestrator.test.ts</code>（7，G3）：轮次上限收口 + 人类发言 重置计数、静默超时 sweep 与幂等、human decision 立即收口、<code>POST /:id/stop</code> 幂等 + 返回取消任务、<code>POST /:id/conclude</code> 留收口说明、<code>group_conclude</code> 工具（decision 落库 + 关群 <ul><li>取消任务数）。</li></ul></li><li><code>packages/groups/src/__tests__/group-speech-v2.test.ts</code>（14，V2-3）：缺省 <code>coordinated</code> 回显与 v1 轮次语义、成员发言不计轮不占预算、人类发言清零并越过发言权；free 模式成员互发 + 换人计轮 <ul><li>到上限收口、连发只算一轮、在线切回 <code>coordinated</code>；预算窗口内第 N+1 条 409 且不落库、 跨窗口恢复、按成员分别计数；<code>@</code> 仲裁（被 @ 者持权、插话 409、回应后转移、协调者改派）、 <code>advisory</code> 只记录、<code>onTurn</code> 回调；<code>getStatus</code> 快照；老库补 <code>speech_mode</code> 列。</li></ul></li><li><code>packages/group-plugin/src/__tests__/portable-store.test.ts</code>（2，V2-3）：便携 JSON store 的 <code>speechMode</code> 缺省/读写，老存档补 <code>coordinated</code>。</li></ul>`,35)])])}const h=o(c,[["render",a]]);export{u as __pageData,h as default};
